import{_ as n,C as r,o as i,c as s,ah as t,E as o}from"./chunks/framework.sPHStHqt.js";const y=JSON.parse('{"title":"Registration","description":"","frontmatter":{},"headers":[],"relativePath":"tenants/registration.md","filePath":"tenants/registration.md","lastUpdated":1789630599000}'),l={name:"tenants/registration.md"};function p(h,e,c,u,g,d){const a=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h1><p><em>This page is for a <strong>tenant</strong> — a business signing up to get its own CRM. If you&#39;re the platform operator creating an account on someone&#39;s behalf, see <a href="/super-admin/tenant-management">Tenant Management</a> instead.</em></p><p>Signing up gives you your own Krayin CRM on your own web address, ready to use the moment you finish. The whole thing takes a few minutes.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to pick a plan and start signing up</li><li>What each step of the sign-up form asks for</li><li>What happens right after you register</li></ul></div><h2 id="start-by-picking-a-plan" tabindex="-1">Start by picking a plan <a class="header-anchor" href="#start-by-picking-a-plan" aria-label="Permalink to &quot;Start by picking a plan&quot;">​</a></h2><p>Registration begins on the pricing page. Choose the plan that fits — you can change it later — and select <strong>Select</strong> (or <strong>Start Free Trial</strong> on the trial).</p>',6)),o(a,{src:"/images/registration/pricing-plans.png",alt:"Choose a plan to start registration"}),e[1]||(e[1]=t('<p>Choosing a plan opens the sign-up form. For more on the plans themselves, see <a href="/tenants/choosing-a-plan">Choosing a Plan</a>.</p><h2 id="the-sign-up-form" tabindex="-1">The sign-up form <a class="header-anchor" href="#the-sign-up-form" aria-label="Permalink to &quot;The sign-up form&quot;">​</a></h2><p>The form has three short steps.</p><h3 id="step-1-—-organization-details" tabindex="-1">Step 1 — Organization Details <a class="header-anchor" href="#step-1-—-organization-details" aria-label="Permalink to &quot;Step 1 — Organization Details&quot;">​</a></h3>',4)),o(a,{src:"/images/registration/register-step1.png",alt:"Registration step 1 — organization details"}),e[2]||(e[2]=t('<ul><li><strong>User Name</strong> <em>(required)</em> — this becomes your web address, so <code>acme</code> gives you <code>acme.yourplatform.com</code>. Use lowercase letters, numbers and single hyphens only. It must be unique — if someone already has it, pick another.</li><li><strong>CName</strong> <em>(optional)</em> — your own domain, if you&#39;d rather use <code>crm.yourbusiness.com</code>. Leave it blank for now; you can add it later. See <a href="/tenants/custom-domains">Custom Domains</a>.</li><li><strong>Description</strong> <em>(required)</em> — a short line about your business.</li></ul><p>Select <strong>Continue</strong>.</p><h3 id="step-2-—-authentication-credentials" tabindex="-1">Step 2 — Authentication Credentials <a class="header-anchor" href="#step-2-—-authentication-credentials" aria-label="Permalink to &quot;Step 2 — Authentication Credentials&quot;">​</a></h3>',3)),o(a,{src:"/images/registration/register-step2.png",alt:"Registration step 2 — credentials"}),e[3]||(e[3]=t('<ul><li><strong>Email</strong> <em>(required)</em> — your sign-in address, and where we&#39;ll reach you. Must not already be in use.</li><li><strong>Password</strong> <em>(required)</em> — at least <strong>6 characters, with one number and one special character</strong>.</li><li><strong>Confirm Password</strong> <em>(required)</em> — type it again to be sure.</li></ul><p>Select <strong>Continue</strong>.</p><h3 id="step-3-—-personal-details" tabindex="-1">Step 3 — Personal Details <a class="header-anchor" href="#step-3-—-personal-details" aria-label="Permalink to &quot;Step 3 — Personal Details&quot;">​</a></h3><p>The last step asks for your <strong>name</strong> and a <strong>phone</strong> number, so we know who to contact.</p><h2 id="what-happens-next" tabindex="-1">What happens next <a class="header-anchor" href="#what-happens-next" aria-label="Permalink to &quot;What happens next&quot;">​</a></h2><p>When you finish, your CRM account is created immediately — pipelines, roles and starter data are all set up for you. Where you go next depends on the plan you chose:</p><ul><li><strong>A free trial</strong> — you&#39;re asked to confirm, then dropped straight into your new CRM. No payment, no card. See <a href="/subscriptions/trials">Free Trials</a>.</li><li><strong>A paid plan</strong> — you&#39;re sent on to pay for your first billing cycle, as below.</li></ul><h2 id="paying-for-a-paid-plan" tabindex="-1">Paying for a paid plan <a class="header-anchor" href="#paying-for-a-paid-plan" aria-label="Permalink to &quot;Paying for a paid plan&quot;">​</a></h2><h3 id="choose-how-to-pay" tabindex="-1">Choose how to pay <a class="header-anchor" href="#choose-how-to-pay" aria-label="Permalink to &quot;Choose how to pay&quot;">​</a></h3><p>After registering, you land on the <strong>Payment Gateways</strong> page.</p>',10)),o(a,{src:"/images/registration/payment-gateway.png",alt:"Payment gateway selection — Stripe"}),e[4]||(e[4]=t('<p>The platform pays through <strong>Stripe</strong>. Select <strong>Subscribe</strong> on the Stripe card to continue.</p><div class="info custom-block"><p class="custom-block-title">For operators</p><p>Stripe has to be connected for this step to appear. If you&#39;re running the platform, set your keys under <a href="/settings/configuration">Configuration → Stripe</a> first — a plan with no gateway price behind it can&#39;t be paid for.</p></div><h3 id="pay-on-stripe" tabindex="-1">Pay on Stripe <a class="header-anchor" href="#pay-on-stripe" aria-label="Permalink to &quot;Pay on Stripe&quot;">​</a></h3><p>Selecting Subscribe takes you to <strong>Stripe&#39;s own secure checkout page</strong>, hosted by Stripe — not the platform.</p>',4)),o(a,{src:"/images/registration/stripe-checkout.png",alt:"Stripe hosted checkout"}),e[5]||(e[5]=t('<p>It shows the plan you&#39;re subscribing to and its price (here, <em>Subscribe to Starter — $19.00 per month</em>), with your email pre-filled. Enter your <strong>card details</strong> and select <strong>Subscribe</strong>. Your card is charged by Stripe, and the subscription is set to renew each cycle until you cancel.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The billing cycle you picked on the pricing page — monthly or yearly — is what Stripe charges for. Switch the toggle <em>before</em> you register if you want the yearly price.</p></div><h3 id="back-to-your-crm" tabindex="-1">Back to your CRM <a class="header-anchor" href="#back-to-your-crm" aria-label="Permalink to &quot;Back to your CRM&quot;">​</a></h3><p>Once Stripe confirms the payment, you&#39;re returned to the platform, your account is activated, your first <a href="/tenants/billing-and-invoices">invoice</a> is raised, and your CRM opens. From then on you sign in at <code>yourusername.yourplatform.com/admin/login</code>.</p><p>If you close the Stripe page without paying, nothing is charged — you can come back and subscribe from <strong>Subscription → Plans</strong> inside your workspace.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Get to know your new CRM → <a href="/tenants/tenant-workspace">The Tenant Workspace</a></li><li>See your invoices and manage the subscription → <a href="/tenants/billing-and-invoices">Billing &amp; Invoices</a></li><li>Compare the plans before you commit → <a href="/tenants/choosing-a-plan">Choosing a Plan</a></li><li>Use your own domain → <a href="/tenants/custom-domains">Custom Domains</a></li></ul>',7))])}const f=n(l,[["render",p]]);export{y as __pageData,f as default};
